// TypeScript mirrors of the Rust v3 surface (spec §四 / §五 / §十一).
//
// Kept intentionally small — `lib/tauri.ts` is the single source of
// truth for IPC; this file only types what crosses that boundary.
//
// Types re-exported from `@corivo/shared-types` are auto-generated by
// `ts-rs` from Rust structs; everything else below is still hand-written
// and migrates one struct at a time as Rust gets `#[derive(TS)]`.

export type { TauriError } from "@corivo/shared-types"

// --------------------------------------------------------------------------
// Frames (spec §五)
// --------------------------------------------------------------------------

export type ExtractionStrategy = "ax" | "ocr" | "ax+ocr" | "skipped";

export interface Frame {
  id: string;
  captured_at: string;
  device_id: string;
  capture_session_id: string;

  app_bundle_id: string | null;
  app_name: string | null;
  window_title: string | null;
  url: string | null;

  screenshot_path: string | null;
  screenshot_hash: string | null;
  screenshot_size_bytes: number | null;

  ax_text: string | null;
  ocr_text: string | null;
  extraction_strategy: ExtractionStrategy;
  extraction_duration_ms: number | null;
  fallback_reason: string | null;

  content_hash: string | null;
  derived_from_frame_id: string | null;
  still_present_until: string | null;

  exclusion_match: string | null;

  created_at: string;
}

export interface ListFramesArgs {
  from?: string | null;
  to?: string | null;
  app_bundle_id?: string | null;
  limit?: number | null;
  offset?: number | null;
}

// --------------------------------------------------------------------------
// Capture pipeline
// --------------------------------------------------------------------------

export type CapturePhase = "running" | "stopped";

export interface CaptureStatus {
  phase: CapturePhase;
  current_session_id: string | null;
  /** RFC3339 UTC instant when the menubar pause expires. `null` means
   *  capture is not paused. Frontend formats the local-time delta for
   *  the sidebar status row. */
  paused_until: string | null;
}

// --------------------------------------------------------------------------
// Config (mirrors Rust `Config`; we only type what the UI actually reads)
// --------------------------------------------------------------------------

export type Language = "zh" | "en";

/** Visual theme preference. Mirrors Rust `ThemePreference`.
 *  `system` follows macOS appearance via `prefers-color-scheme`. */
export type ThemePreference = "light" | "dark" | "system";

export interface AppConfig {
  minimize_to_tray: boolean;
  /** Language Corivo's interface is rendered in. Mirrors
   *  `Config.app.ui_language` on the Rust side. */
  ui_language: Language;
  /** Language the AI replies in inside `/ask` and Quick Ask. Mirrors
   *  `Config.app.response_language` on the Rust side. Independent from
   *  `ui_language` so a Chinese-UI user can still get English answers
   *  (and vice versa). */
  response_language: Language;
  start_capture_on_launch: boolean;
  onboarding_completed: boolean;
  onboarding_version: number;
  onboarding_step: string | null;
  /** Visual theme. `useThemeSync` hook applies `[data-theme]` on
   *  `<html>` based on this. Default `system`. */
  theme: ThemePreference;
  /** Onboarding handoff flag — `false` until the user completes their
   *  very first Quick Ask turn during the Try-It step. Quick Ask reads
   *  this to decide whether to show the 3 suggestion chips and to fire
   *  the `onboarding:first-quick-ask` event so the onboarding window
   *  can dismiss itself. Once flipped to `true` it stays true for the
   *  life of the install — the chips never come back. */
  first_quick_ask_done: boolean;
  /** RFC3339 UTC instant the menubar pause expires. `null` when not
   *  paused. The backend's tray menu owns this field; the frontend
   *  reads it via `CaptureStatus` rather than `Config` for live updates. */
  capture_paused_until: string | null;
  /** Hidden "developer mode" toggle, unlocked by triple-clicking the
   *  settings dialog title. When `true`, the settings sidebar surfaces a
   *  "Developer" section with WebView DevTools + on-device debugging
   *  shortcuts. Disable from inside the section itself. Default false. */
  developer_mode: boolean;
}

export interface CaptureConfig {
  interval_secs: number;
  batch_size: number;
  max_storage_gb: number;
  jpeg_quality: number;
  broadcast_capacity: number;
}

export interface PromptDebugConfig {
  summary_override: string | null;
  push_judgment_override: string | null;
  suggest_override: string | null;
  score_override: string | null;
}

export interface SoulConfig {
  preset: "gentle" | "accomplice" | "old_friend" | "coach" | "custom";
  custom_text: string | null;
}

export interface UserModelConfig {
  batcher: { min_batch_size: number; flush_interval_ms: number };
  retrieval: {
    w_confidence: number;
    w_decay: number;
    k_decay_days: number;
    limit_multiplier: number;
  };
  pipeline: { similar_pool_size: number; min_draft_count: number };
}

export interface ReconcileConfig {
  enabled: boolean;
  merge_enabled: boolean;
  stream_enabled: boolean;
  interval_hours: number;
  min_workcontexts_per_project_for_stream: number;
}

export interface FocusSessionConfig {
  enabled: boolean;
  gap_minutes: number;
  idle_close_multiplier: number;
  max_session_hours: number;
}

export interface Config {
  capture: CaptureConfig;
  app: AppConfig;
  prompt_debug: PromptDebugConfig;
  user_model: UserModelConfig;
  soul: SoulConfig;
  reconcile: ReconcileConfig;
  focus_session: FocusSessionConfig;
  exec_agent: ExecAgentConfig;
  corivo_session: CorivoSessionConfig;
}

export interface CorivoSessionConfig {
  /** Closed-beta bearer token pair persisted in `config.json`
   *  alongside everything else. `null` ↔ "not logged in". */
  session_token: string | null;
}

// --------------------------------------------------------------------------
// Exec-agent auth (spec §7.4).
// --------------------------------------------------------------------------

export type ExecAgentAuthMode = "corivo_proxy" | "byok" | "chatgpt";

/** Mirror of Rust `ChatgptAuthConfig` — persisted ChatGPT subscription
 *  creds. The UI only reads `account_id` to decide "signed-in" + the
 *  email / plan for the status pane; tokens themselves never leave the
 *  Rust side. */
export interface ChatgptAuthConfig {
  access_token: string | null;
  refresh_token: string | null;
  id_token: string | null;
  account_id: string | null;
  plan_type: string | null;
  email: string | null;
  /** RFC3339 absolute expiry. The Rust runtime refreshes the token
   *  ~5 min before this hits. */
  expires_at: string | null;
}

/** Mirror of Rust `ChatgptAuthStatus` — the stripped-down view the
 *  Settings status pane consumes. Token material never crosses this
 *  boundary. */
export interface ChatgptAuthStatusView {
  signedIn: boolean;
  email: string | null;
  planType: string | null;
  expiresAt: string | null;
  accountId: string | null;
}

// Closed-beta auth surface + skill listing — ts-rs generated, single
// source of truth.
export type {
  ApiShape,
  AuthStatus,
  AvailableSkill,
  AvailableSkillKind,
  AvailableSkillSource,
  ThinkingLevel,
} from "@corivo/shared-types";

import type { ApiShape, ThinkingLevel } from "@corivo/shared-types";

export interface SkillShareConfig {
  enabled: string[];
  initialized: boolean;
}

export interface ExecAgentConfig {
  auth_mode: ExecAgentAuthMode;
  /** CorivoProxy mode: id of the model the user picked from the
   *  cached `/v1/models` list (spec §7.2). Sidecar resolves api_shape
   *  + compaction partner via the cache. `null` → no model selected
   *  yet (the picker UI nudges the user to choose). */
  selected_model_id: string | null;
  /** Byok mode: provider protocol shape pi-ai uses inside the sidecar. */
  byok_api_shape: ApiShape | null;
  /** Byok mode: optional override for the provider base URL. `null`
   *  falls back to the SDK default. */
  byok_base_url: string | null;
  /** Byok mode: user-supplied API key. */
  byok_key: string | null;
  /** Byok mode: user-supplied model id (e.g. `gpt-4o`). Validated by
   *  the sidecar against `/v1/models` on startup. */
  byok_model: string | null;
  /** Reasoning budget the sidecar forwards to pi-ai on the main turn. */
  thinking_level: ThinkingLevel;
  skill_share: SkillShareConfig;
  /** ChatGPT subscription tokens. Empty/null when the user is not
   *  signed in with ChatGPT. The Settings UI calls
   *  `chatgpt_auth_login` / `_logout` to mutate this — never edited
   *  by direct `setConfig`. */
  chatgpt: ChatgptAuthConfig;
}

