// --------------------------------------------------------------------------
// Chat / `/ask` (spec §五 + §八 + §十一)
// --------------------------------------------------------------------------

// `ChatRole`, `ContentBlock`, `MessageStatus`, `Usage` are ts-rs generated
// — the Rust definitions in `domain::chat` are the single source of truth.
export type {
  ChatRole,
  ContentBlock,
  MessageStatus,
  Usage,
} from "@corivo/shared-types";

import type {
  ChatRole,
  ContentBlock,
  MessageStatus,
  Usage,
} from "@corivo/shared-types";

export interface ChatThread {
  id: string;
  title: string | null;
  /** Spec §8.2: model the thread was created against. Sidecar reads
   *  this instead of the live Settings selection so a mid-conversation
   *  Settings switch doesn't derail the active turn. The thread list
   *  UI surfaces the corresponding `display_name` as a small badge. */
  bound_model_id: string;
  bound_api_shape: ApiShape;
  /** v1300 sidebar lifecycle. ISO timestamp when the user pinned the
   *  thread; `null` when not pinned. The sidebar groups pinned threads
   *  under a "置顶" section above "最近". */
  pinned_at: string | null;
  /** v1300 sidebar lifecycle. ISO timestamp when the user archived
   *  the thread; `null` when not archived. Archived threads are
   *  hidden from "最近" and surfaced only when the "归档(N)"
   *  disclosure expands. Archive dominates pin in the UI. */
  archived_at: string | null;
  created_at: string;
  updated_at: string;
}

/** v1200 chat_messages row. `content_blocks` is the canonical rich
 *  representation — text / thinking / tool_use / tool_result /
 *  focus_context / frame_citation; `content_text` is the plain-text
 *  rollup (concat of all text + thinking) for FTS / sidebar preview.
 *
 *  `status` distinguishes `complete` (terminal, normal turn) /
 *  `streaming` (assistant placeholder still being filled — filtered
 *  out of by-thread reads) / `error` / `cancelled`. */
export interface ChatMessage {
  id: string;
  thread_id: string;
  role: ChatRole;
  content_blocks: ContentBlock[];
  content_text: string;
  cited_frame_ids: string[] | null;
  status: MessageStatus;
  error_message: string | null;
  finish_reason: string | null;
  usage: Usage | null;
  /** Model directory alias that actually drove this assistant turn —
   *  set by the backend right after runtime resolution. `null` for
   *  user rows, for BYOK assistant rows (no alias to track), and for
   *  legacy assistant rows from before v1301. UI should treat `null`
   *  as "unknown model" rather than a bug. */
  model_used: string | null;
  created_at: string;
  updated_at: string | null;
}

/** JSON-Lines stream event the recall orchestrator pushes over the
 *  Tauri Channel (spec §八 — Phase 3 uses a custom shape; Phase 3.5
 *  may swap to Vercel AI SDK Data Stream Protocol). */
export type ChatStreamEvent =
  | { type: "text-delta"; text: string }
  | {
      type: "tool-call";
      id: string;
      name: string;
      args: Record<string, unknown>;
    }
  | { type: "tool-result"; id: string; result: unknown }
  | { type: "cited-frames"; frame_ids: string[] }
  | {
      /** Transient progress hint that doesn't change message content.
       *  Currently emitted as `kind: "api-retry"` while the SDK retries
       *  failed HTTP requests so the UI doesn't sit silent for the full
       *  backoff. Cleared when actual content (text/tool/finish/error)
       *  arrives. */
      type: "status";
      kind: string;
      detail: string | null;
    }
  | {
      type: "finish";
      // `cancelled` is emitted by the corivo-agent runner when
      // `exec_agent_cancel` fires the per-thread cancel signal. The UI
      // treats it as a neutral end-of-stream (no error chrome) — the
      // partial assistant content is kept and persisted as-is.
      reason: "end-turn" | "truncated" | "error" | "cancelled";
    }
  | { type: "error"; message: string };

// --------------------------------------------------------------------------
// Quick Ask (spec §六 + §八 + §十一)
// --------------------------------------------------------------------------

export interface FocusContext {
  frame_id: string;
  captured_at: string;
  app_bundle_id: string | null;
  app_name: string | null;
  window_title: string | null;
  url: string | null;
  adapter_name: string | null;
  /** Adapter-specific structured payload — opaque to the UI except a
   *  couple of well-known keys (`url`, `path`, `cwd`) the FocusCard
   *  may surface as a subtitle. */
  adapter_payload: Record<string, unknown> | null;
  /** First-pass extraction (AX or OCR text). The window shows the
   *  first ~200 chars; the full body can be fetched via
   *  `get_frame_text(frame_id)` from the recall toolset. */
  primary_text: string;
  /** User's currently-highlighted text on the focused window,
   *  captured via the AX `AXSelectedTextMarkerRange` post-step.
   *  `null` when there's no active selection or the host app
   *  doesn't expose marker ranges. Quick Ask passes this to the
   *  agent as a separate "用户高亮选区" block alongside `primary_text`. */
  selection: string | null;
  excluded: boolean;
  empty: boolean;
}

/** Subset of FocusContext available right after probe + screenshot.
 *  Sent in the `quick-ask:opened` event when the AX walk is still
 *  pending — FocusCard renders the title row from this and the full
 *  FocusContext arrives later via `quick-ask:focus-ready`. */
export interface QuickAskSkeleton {
  captured_at: string;
  app_bundle_id: string | null;
  app_name: string | null;
  window_title: string | null;
  url: string | null;
}

/** Discriminated payload of the `quick-ask:opened` event. The
 *  `pending` variant is emitted on the fast path (window shown
 *  immediately, AX walk in flight); the `ready` variant is emitted
 *  when the focus app is on the exclusion list and there's no
 *  extraction work left to do.
 *
 *  Note: no `thread` field. Quick Ask uses type-to-create — the
 *  `chat_threads` row materializes in the frontend on the first send
 *  via `useChatStream::createThreadIfMissing`, same as `/ask`. */
export type QuickAskOpenedPayload =
  | {
      kind: "pending";
      skeleton: QuickAskSkeleton;
    }
  | {
      kind: "ready";
      focus: FocusContext;
    };

/** Quick Ask hotkey shape. The backend reports the platform-specific
 * bare-modifier gesture so the UI can render Option on macOS and Alt
 * on Windows without guessing. */
export type HotkeyBinding = "double_tap_option" | "double_tap_alt";

export interface HotkeyStatus {
  binding: HotkeyBinding;
  installed: boolean;
  error: string | null;
}
